import{_ as h,C as r,o as t,c,a3 as i,b as s,w as o,a,E as g,a4 as l}from"./chunks/framework.MGD2uYU7.js";const I=JSON.parse('{"title":"Use Case Specification — AnPhucRealEstate v1","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03-use-cases.md","filePath":"guide/03-use-cases.md","lastUpdated":null}'),u={name:"guide/03-use-cases.md"};function d(p,n,E,A,C,m){const e=r("Mermaid");return t(),c("div",null,[n[1]||(n[1]=i('<h1 id="use-case-specification-—-anphucrealestate-v1" tabindex="-1">Use Case Specification — AnPhucRealEstate v1 <a class="header-anchor" href="#use-case-specification-—-anphucrealestate-v1" aria-label="Permalink to &quot;Use Case Specification — AnPhucRealEstate v1&quot;">​</a></h1><p><strong>Status</strong>: In Review — <strong>Author</strong>: Alex (PM) — <strong>Updated</strong>: 2026-10-09 — <strong>v1.1</strong> (review pass: sửa heading UC-09 bị dính dòng Links, AF-3/AF-4 UC-01 reset password, EF-3 UC-07 → 410 đồng bộ docs/06, EF-5 UC-08 trỏ đúng BR-AU-17) <strong>Ký hiệu</strong>: UC-xx use case; luồng chính MF-n; luồng thay thế AF; luồng ngoại lệ EF. Links: BR = docs/08, FR = docs/02, API = docs/06, Flow = docs/04, TC = docs/09.</p><h2 id="_1-actors" tabindex="-1">1. Actors <a class="header-anchor" href="#_1-actors" aria-label="Permalink to &quot;1. Actors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Role hệ thống</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Khách</strong></td><td><code>GUEST</code></td><td>Chưa xác thực. Chỉ browse public.</td></tr><tr><td><strong>Thành viên</strong></td><td><code>USER</code></td><td>Đã đăng ký; có thể là người mua và/hoặc chủ nhà (sau KYC).</td></tr><tr><td><strong>Quản trị viên</strong></td><td><code>ADMIN</code></td><td>Nhân viên An Phuc: duyệt KYC/tin, vận hành đấu giá, xử lý thanh toán thủ công, dashboard.</td></tr></tbody></table><h2 id="_2-use-case-diagram-tong-quan" tabindex="-1">2. Use Case Diagram (tổng quan) <a class="header-anchor" href="#_2-use-case-diagram-tong-quan" aria-label="Permalink to &quot;2. Use Case Diagram (tổng quan)&quot;">​</a></h2>',5)),(t(),s(l,null,{default:o(()=>[g(e,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20Actors%0A%20%20%20%20G((Kh%C3%A1ch))%3B%20U((Th%C3%A0nh%20vi%C3%AAn))%3B%20A((Qu%E1%BA%A3n%20tr%E1%BB%8B%20vi%C3%AAn))%0A%20%20end%0A%20%20subgraph%20%22H%E1%BB%87%20th%E1%BB%91ng%20AnPhucRealEstate%20v1%22%0A%20%20%20%20UC01(%5BUC-01%20%C4%90%C4%83ng%20k%C3%BD%20%2F%20%C4%90%C4%83ng%20nh%E1%BA%ADp%5D)%0A%20%20%20%20UC02(%5BUC-02%20N%E1%BB%99p%20%26%20duy%E1%BB%87t%20KYC%5D)%0A%20%20%20%20UC03(%5BUC-03%20Xem%20tin%20%26%20phi%C3%AAn%20%C4%91%E1%BA%A5u%20gi%C3%A1%5D)%0A%20%20%20%20UC04(%5BUC-04%20%C4%90%E1%BA%B7t%20l%E1%BB%8Bch%20xem%20nh%C3%A0%5D)%0A%20%20%20%20UC05(%5BUC-05%20T%E1%BA%A1o%20%26%20qu%E1%BA%A3n%20l%C3%BD%20tin%20%C4%91%C4%83ng%5D)%0A%20%20%20%20UC06(%5BUC-06%20Duy%E1%BB%87t%20tin%20%C4%91%C4%83ng%5D)%0A%20%20%20%20UC07(%5BUC-07%20%C4%90%C4%83ng%20k%C3%BD%20%C4%91%E1%BA%A5u%20gi%C3%A1%20%2B%20c%E1%BB%8Dc%5D)%0A%20%20%20%20UC08(%5BUC-08%20%C4%90%E1%BA%A5u%20gi%C3%A1%20tr%E1%BB%B1c%20ti%E1%BA%BFp%5D)%0A%20%20%20%20UC09(%5BUC-09%20Thanh%20to%C3%A1n%20phi%C3%AAn%20tr%C3%BAng%5D)%0A%20%20%20%20UC10(%5BUC-10%20Mua%20g%C3%B3i%20VIP%5D)%0A%20%20%20%20UC11(%5BUC-11%20T%E1%BA%A1o%20%26%20c%C3%B4ng%20b%E1%BB%91%20phi%C3%AAn%5D)%0A%20%20%20%20UC12(%5BUC-12%20Qu%E1%BA%A3n%20l%C3%BD%20ng%C6%B0%E1%BB%9Di%20d%C3%B9ng%5D)%0A%20%20end%0A%20%20G%20--%3E%20UC01%20%26%20UC03%0A%20%20U%20--%3E%20UC01%20%26%20UC02%20%26%20UC03%20%26%20UC04%20%26%20UC05%20%26%20UC07%20%26%20UC08%20%26%20UC09%20%26%20UC10%0A%20%20U%20-.%20%22%3C%3Cinclude%3E%3E%20ch%E1%BB%A7%20nh%C3%A0%22.-%3E%20UC04%0A%20%20A%20--%3E%20UC02%20%26%20UC06%20%26%20UC11%20%26%20UC12%0A%20%20A%20-.%20%22extend%3A%20x%E1%BB%AD%20l%C3%BD%20payment%20th%E1%BB%A7%20c%C3%B4ng%22.-%3E%20UC09%0A"})]),fallback:o(()=>[...n[0]||(n[0]=[a(" Loading... ",-1)])]),_:1})),n[2]||(n[2]=i('<hr><h2 id="uc-01-—-đang-ky-tai-khoan-đang-nhap" tabindex="-1">UC-01 — Đăng ký tài khoản &amp; Đăng nhập <a class="header-anchor" href="#uc-01-—-đang-ky-tai-khoan-đang-nhap" aria-label="Permalink to &quot;UC-01 — Đăng ký tài khoản &amp; Đăng nhập&quot;">​</a></h2><p><strong>Actor</strong>: Khách (chính); Thành viên (đăng nhập lại) <strong>Preconditions</strong>: Không có. <strong>Postconditions</strong>: Tài khoản <code>status=PENDING_KYC</code>? — <strong>Không</strong>: user tạo ra <code>status=ACTIVE</code>, <code>kycStatus=NONE</code>; session phát hành.</p><p><strong>Main Flow (MF)</strong></p><ol><li>Khách nhập email + password + họ tên → Submit.</li><li>Hệ thống validate (FR-IDT-01), tạo user, hash argon2id.</li><li>Hệ thống tự đăng nhập: trả access 15p + refresh 7d, redirect Dashboard.</li></ol><p><strong>Alternative Flows</strong></p><ul><li>AF-1 Đăng nhập bằng tài khoản đã có: MF rút gọn bước 1–2 → validate credentials → phát token.</li><li>AF-2 Access hết hạn giữa phiên: FE gọi silent refresh (<code>POST /auth/refresh</code>) → tiếp tục, khách không nhận thấy.</li><li>AF-3 Quên mật khẩu: <strong>không có trong v1</strong> — khách liên hệ CS, ADMIN reset thủ công: sinh mật khẩu tạm (bắt buộc đổi lần đăng nhập đầu), thu hồi toàn bộ refresh, gửi email, ghi audit <code>USER_RESET_PASSWORD</code> (FR-IDT-07). Flow reset tự quên mật khẩu là v1.1 (docs/10 §7).</li><li>AF-4 ADMIN reset password (xem AF-3) — endpoint <code>POST /admin/users/{id}/reset-password</code>, reason bắt buộc 5–500 ký tự.</li></ul><p><strong>Exception Flows</strong></p><ul><li>EF-1 Email trùng → 409 <code>AUTH_EMAIL_TAKEN</code>, form báo &quot;Email đã được sử dụng&quot;.</li><li>EF-2 Password yếu → 400 <code>VALIDATION_ERROR</code> theo field.</li><li>EF-3 Sai credentials 5 lần/15 phút → 429 <code>RATE_LIMITED</code>, khóa 15 phút theo IP.</li><li>EF-4 Refresh reuse detected → thu hồi cả token family, yêu cầu đăng nhập lại (EF hiển thị &quot;Phiên hết hạn, đăng nhập lại&quot;).</li></ul><p><strong>Links</strong>: FR-IDT-01..05, BR-IDT-01..05, <code>POST /auth/register|login|refresh|logout</code>, UC diagram docs/04 F-00.</p><hr><h2 id="uc-02-—-nop-ho-so-kyc-cccd-duyet" tabindex="-1">UC-02 — Nộp hồ sơ KYC (CCCD) &amp; Duyệt <a class="header-anchor" href="#uc-02-—-nop-ho-so-kyc-cccd-duyet" aria-label="Permalink to &quot;UC-02 — Nộp hồ sơ KYC (CCCD) &amp; Duyệt&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên (nộp), Quản trị viên (duyệt) <strong>Preconditions</strong>: User ACTIVE; chưa có KYC APPROVED. <strong>Postconditions</strong>: <code>kyc_applications.status ∈ {APPROVED, REJECTED}</code>; user.kycStatus cập nhật; NTF-02 gửi.</p><p><strong>MF (phía USER)</strong></p><ol><li>Dashboard nhắc &quot;Xác minh danh tính&quot; → màn KYC.</li><li>Nhập họ tên, DOB, CCCD 12 số; upload ảnh 2 mặt CCCD (qua <code>POST /media/upload</code> kind=kyc_doc).</li><li>Submit → status PENDING; hiển thị &quot;Đang duyệt, SLA 48h&quot;.</li></ol><p><strong>MF (phía ADMIN)</strong></p><ol><li>Mở <code>/admin/kyc-queue</code> (sort quá SLA trước).</li><li>Xem hồ sơ (signed URL ảnh), đối chiếu dữ liệu.</li><li>Chọn Approve → ghi nhận; hoặc Reject + reason bắt buộc.</li><li>Hệ thống lưu reviewedBy/At, bắn event, NTF tới user.</li></ol><p><strong>Alternative Flows</strong></p><ul><li>AF-1 ADMIN cần thêm ảnh (mờ): Reject với reason yêu cầu chụp lại → user nộp lại (đếm giới hạn 3 lần/30 ngày).</li><li>AF-2 Nộp lại sau REJECTED: giữ hồ sơ cũ <code>SUPERSEDED</code>? — Không: mỗi lần nộp tạo 1 application mới; queue hiển thị application PENDING gần nhất; user chỉ có 1 PENDING tại một thời điểm (BR-KYC-05).</li></ul><p><strong>Exception Flows</strong></p><ul><li>EF-1 CCCD đã APPROVED trên tài khoản khác → 409 <code>KYC_ID_ALREADY_VERIFIED</code> — &quot;Giấy tờ này đã được liên kết tài khoản khác, liên hệ CS&quot;.</li><li>EF-2 Dưới 18 tuổi → 422 <code>KYC_UNDERAGE</code>.</li><li>EF-3 Quá 3 lần nộp/30 ngày → 422 <code>KYC_ATTEMPT_LIMIT</code>, hướng dẫn liên hệ CS.</li><li>EF-4 ADMIN duyệt application không còn PENDING (ai đó duyệt trước) → 409 <code>INVALID_TRANSITION</code>, queue refresh.</li></ul><p><strong>Links</strong>: FR-KYC-01..05, BR-KYC-01..06, flow docs/04 F-05.</p><hr><h2 id="uc-03-—-xem-tin-đang-thong-tin-phien-đau-gia-public-browse" tabindex="-1">UC-03 — Xem tin đăng &amp; thông tin phiên đấu giá (public browse) <a class="header-anchor" href="#uc-03-—-xem-tin-đang-thong-tin-phien-đau-gia-public-browse" aria-label="Permalink to &quot;UC-03 — Xem tin đăng &amp; thông tin phiên đấu giá (public browse)&quot;">​</a></h2><p><strong>Actor</strong>: Khách, Thành viên <strong>Preconditions</strong>: Có dữ liệu LISTED/PUBLISHED (seed OQ-7). <strong>Postconditions</strong>: Không thay đổi trạng thái (read-only, log truy vấn).</p><p><strong>MF</strong></p><ol><li>Khách vào Trang chủ → xem các khối: tin mới, phiên sắp mở, dự án tiêu biểu.</li><li>Tìm kiếm/filter (dự án, khoảng giá, diện tích, sort) → danh sách pagination.</li><li>Click tin → Detail: ảnh gallery, thông số, giá, trạng thái (Đang bán / Sắp đấu giá / Đã bán), nút [&quot;Đặt lịch xem&quot; nếu LISTED &amp; đã đăng nhập] / [&quot;Xem phiên đấu giá&quot; nếu RESERVED có phiên].</li><li>Tab &quot;Đấu giá&quot; → list phiên upcoming/live/ended; click → Auction detail: quy chế, giá mở đầu, bước giá, cọc, timeline, số người tham gia (pseudonym, chỉ khi published).</li></ol><p><strong>Alternative Flows</strong></p><ul><li>AF-1 Không đăng nhập bấm hành động cần tài khoản → modal &quot;Đăng nhập để tiếp tục&quot;, quay lại đúng intent (deep-link return).</li><li>AF-2 Tin của chính mình → chủ thấy đầy đủ (kể cả certSerial, docs) + nút quản lý.</li></ul><p><strong>Exception Flows</strong></p><ul><li>EF-1 Tin không còn LISTED (vừa bị rút) → 404 <code>HOUSING_NOT_FOUND</code> + trang &quot;Tin không khả dụng, xem tin tương tự cùng dự án&quot; (tương tự = cùng projectId, sort newest — <strong>không phải AI</strong>).</li><li>EF-2 Filter vô nghiệp (priceMin &gt; priceMax) → FE chặn trước; BE ignore cặp vô hiệu.</li></ul><p><strong>Links</strong>: FR-HS-06/07, FR-AU-05, UC-03 diagram; TC-HS-01..04.</p><hr><h2 id="uc-04-—-đat-lich-xem-nha" tabindex="-1">UC-04 — Đặt lịch xem nhà <a class="header-anchor" href="#uc-04-—-đat-lich-xem-nha" aria-label="Permalink to &quot;UC-04 — Đặt lịch xem nhà&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên (KYC APPROVED) — người mua; Thành viên — chủ nhà; ADMIN (giám sát) <strong>Preconditions</strong>: Tin LISTED; user KYC APPROVED. <strong>Postconditions</strong>: <code>viewing_requests.status</code> PENDING→CONFIRMED→COMPLETED (hoặc REJECT/EXPIRED); NTF cả hai phía.</p><p><strong>MF</strong></p><ol><li>Người mua tại detail tin → &quot;Đặt lịch xem&quot; → chọn ngày/giờ trong [now+24h, now+14d], khung 08:00–20:00.</li><li>Submit → PENDING; chủ nhà nhận NTF.</li><li>Chủ nhà mở danh sách yêu cầu → Xác nhận / Từ chối (reason).</li><li>CONFIRMED: cả hai thấy lịch tại &quot;Lịch của tôi&quot;; sau giờ hẹn +2h nếu chưa COMPLETE → job tự EXPIRED; chủ nhà bấm &quot;Hoàn tất&quot;.</li></ol><p><strong>AF</strong>: AF-1 Người mua tự hủy trước khi confirm/cancel (→ CANCELLED). AF-2 ADMIN can thiệp khiếu nại: đánh dấu COMPLETED/EXPIRED manual (audit). <strong>EF</strong>: EF-1 slot &lt; 24h → 422 <code>VIEWING_SLOT_INVALID</code>. EF-2 &gt; 3 PENDING → 422 <code>VIEWING_LIMIT</code>. EF-3 tin không còn LISTED → 409. EF-4 chủ nhà không phản hồi 24h → NTF nhắc; user có thể cancel.</p><p><strong>Links</strong>: FR-VW-01..04, BR-VW-01..04.</p><hr><h2 id="uc-05-—-chu-nha-tao-quan-ly-tin-đang" tabindex="-1">UC-05 — Chủ nhà tạo &amp; quản lý tin đăng <a class="header-anchor" href="#uc-05-—-chu-nha-tao-quan-ly-tin-đang" aria-label="Permalink to &quot;UC-05 — Chủ nhà tạo &amp; quản lý tin đăng&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên (đã KYC APPROVED) <strong>Preconditions</strong>: KYC APPROVED; hạn mức tin active chưa vượt (FREE=2). <strong>Postconditions</strong>: Tin <code>LISTED</code> sau khi ADMIN duyệt; hoặc REJECTED/WITHDRAWN.</p><p><strong>MF</strong></p><ol><li>&quot;Đăng bán&quot; → form đa bước (docs/05 SC-22): (a) chọn dự án + mã căn + diện tích/tầng/giá; (b) loại pháp lý + số sổ; (c) upload 3–15 ảnh + 1–6 PDF; (d) mô tả; (e) xác nhận &amp; xem trước.</li><li>&quot;Lưu nháp&quot; → DRAFT, hoặc &quot;Gửi duyệt&quot; → IN_REVIEW.</li><li>ADMIN duyệt (UC-06) → APPROVED ⇒ status LISTED, hiển thị public, NTF-01.</li><li>Chủ quản lý: sửa (khi DRAFT/REJECTED), rút LISTED → WITHDRAWN.</li></ol><p><strong>AF</strong></p><ul><li>AF-1 Submit khi vượt hạn mức → modal bán VIP (upsell) → UC-10 → quay lại submit.</li><li>AF-2 Số sổ đã bị tài khoản khác claim → 409, hướng dẫn CS (BR-HS-03).</li><li>AF-3 Giá vượt trần dự án → 422 <code>PRICE_ABOVE_CAP</code> với số liệu trần cụ thể để chủ chỉnh.</li></ul><p><strong>EF</strong></p><ul><li>EF-1 KYC chưa APPROVED → CTA chuyển sang UC-02.</li><li>EF-2 Ảnh sai MIME/quá 5MB → FE reject trước, BE 400 <code>VALIDATION_ERROR</code>.</li><li>EF-3 REJECTED → chủ sửa và submit lại, đếm giới hạn 5 lần/30 ngày (EF: <code>RESUBMIT_LIMIT</code> 422).</li><li>EF-4 Sửa tin đang RESERVED (có phiên) → 409 <code>LISTING_LOCKED</code>.</li></ul><p><strong>Links</strong>: FR-HS-02..05/09/10, BR-HS-01..10, flow docs/04 F-04.</p><hr><h2 id="uc-06-—-admin-duyet-tin-đang" tabindex="-1">UC-06 — ADMIN duyệt tin đăng <a class="header-anchor" href="#uc-06-—-admin-duyet-tin-đang" aria-label="Permalink to &quot;UC-06 — ADMIN duyệt tin đăng&quot;">​</a></h2><p><strong>Actor</strong>: Quản trị viên <strong>Preconditions</strong>: Tồn tại tin <code>IN_REVIEW</code>. <strong>Postconditions</strong>: APPROVED (→LISTED) hoặc REJECTED(reason); NTF-01; audit.</p><p><strong>MF</strong>: Queue <code>/admin/housing?status=IN_REVIEW</code> (SLA 24h) → mở hồ sơ → đối chiếu: pháp lý (sổ), giá vs cap, ảnh đúng căn, thông tin thống nhất → Approve/Reject(reason) → ghi audit. <strong>AF-1</strong>: Cần bổ sung → Reject với reason hướng dẫn. <strong>AF-2</strong>: Nghi vấn pháp lý (sổ tranh chấp) → Reject + tag nội bộ <code>legal_review</code>? — v1: chỉ reason text, escalation ngoài hệ thống (CS phone) — ghi chú OQ-4. <strong>EF-1</strong>: Hai ADMIN cùng duyệt → 409 <code>INVALID_TRANSITION</code> cho người sau, toast &quot;Hồ sơ vừa được xử lý bởi {name}&quot;. <strong>EF-2</strong>: Approve tin có certSerial bị claim trong lúc chờ (hiếm) → 409 <code>CERT_ALREADY_CLAIMED</code>, reject lại thực tế.</p><p><strong>Links</strong>: FR-ADM-01/02, BR-HS-07..09.</p><hr><h2 id="uc-07-—-đang-ky-tham-gia-phien-đat-coc" tabindex="-1">UC-07 — Đăng ký tham gia phiên &amp; đặt cọc <a class="header-anchor" href="#uc-07-—-đang-ky-tham-gia-phien-đat-coc" aria-label="Permalink to &quot;UC-07 — Đăng ký tham gia phiên &amp; đặt cọc&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên (KYC APPROVED, ACTIVE) <strong>Preconditions</strong>: Phiên PUBLISHED, now &lt; regDeadline (= start − 24h); user không phải chủ listing. <strong>Postconditions</strong>: registration ACTIVE với cọc PAID, cấp pseudonym; hoặc REJECTED/EXPIRED.</p><p><strong>MF</strong></p><ol><li>Auction detail → &quot;Đăng ký tham gia&quot; (đọc quy chế modal bắt buộc scroll-bottom + tick đồng ý — <strong>không tự suy đoán điều khoản, hiện text từ BR</strong>).</li><li>Hệ thống kiểm điều kiện (KYC, không trùng registration, không phải chủ) → tạo registration PENDING_DEPOSIT, tính <code>depositAmount = round_down(openingPrice × depositPercent/100)</code>, min 10.000.000đ (BR-AU-06).</li><li>User thanh toán qua VNPay (hoặc chuyển khoản thủ công — lấy nội dung bill) → webhook/ADMIN confirm → registration <strong>ACTIVE</strong>; hiển thị pseudonym <code>TV-XXXX</code>, mã số tham gia.</li><li>NTF xác nhận + nhắc lịch (FR-NTF-03).</li></ol><p><strong>AF</strong></p><ul><li>AF-1 Manual transfer: user nộp, đối chiếu <code>content bill = ANPHUC &lt;paymentId&gt;</code>; ADMIN confirm tại <code>/admin/payments</code> → ACTIVE. Có SLA: ADMIN xác nhận ≤ 2h trong giờ làm việc; nếu sát regDeadline user được báo &quot;chờ duyệt&quot;.</li><li>AF-2 Payment intent quá 6h → EXPIRED → user tạo intent mới (không giới hạn số lần trong window).</li></ul><p><strong>EF</strong></p><ul><li>EF-1 Sau regDeadline → 410 <code>AUCTION_REG_CLOSED</code>.</li><li>EF-2 Đăng ký 2 lần → 409 <code>DUPLICATE_REGISTRATION</code>.</li><li>EF-3 User SUSPENDED quyền đấu giá (do vi phạm trước) → 403 <code>AUCTION_PRIVILEGE_SUSPENDED</code>.</li><li>EF-4 Deposit đã có nhưng phiên bị ADMIN cancel trước start → refund tự động (BR-AU-19, BR-PAY-05), NTF-05.</li></ul><p><strong>Links</strong>: FR-AU-03/04, FR-PAY-01..03, BR-AU-05..07, flow docs/04 F-02.</p><hr><h2 id="uc-08-—-đau-gia-truc-tiep-live-bidding" tabindex="-1">UC-08 — Đấu giá trực tiếp (live bidding) <a class="header-anchor" href="#uc-08-—-đau-gia-truc-tiep-live-bidding" aria-label="Permalink to &quot;UC-08 — Đấu giá trực tiếp (live bidding)&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên có registration ACTIVE; ADMIN (giám sát); Khách (xem kết quả ended) <strong>Preconditions</strong>: now ∈ [startAt, endAt); phiên IN_PROGRESS (job chuyển PUBLISHED→IN_PROGRESS tại startAt). <strong>Postconditions</strong>: phiên AWARDED/FAILED; order tạo nếu AWARDED; cọc refund/forfeit; NTF-04.</p><p><strong>MF</strong></p><ol><li>Người mua vào live page: countdown, giá hiện tại, bid feed (pseudonym + amount + time), lịch sử bước giá.</li><li>Bấm &quot;+ Bước giá&quot; / &quot;+2×&quot; / nhập số tùy chọn (≥ current + step) → Xác nhận (modal chốt lần cuối).</li><li>POST bid → 201: bid feed cập nhật, user là current leader (badge &quot;Bạn đang dẫn đầu&quot;).</li><li>FE re-fetch/poll 5s (quyết định v1 — WS ở v1.1, docs/05 §4.6).</li><li><strong>Anti-snipe</strong>: bid trong 60s cuối → endAt += 60s, banner &quot;Phiên kéo dài thêm 60 giây&quot;.</li><li>Hết giờ (không còn bid trong 60s cuối): job kết thúc — 0 bid → FAILED (tin trở lại LISTED); ≥1 → AWARDED: người trả cao nhất trúng; feed khóa; hiển thị kết quả + tạo order (UC-09).</li></ol><p><strong>AF</strong></p><ul><li>AF-1 Phiên chưa bắt đầu (PUBLISHED) → page hiển thị &quot;Sắp diễn ra&quot;, disabled bid.</li><li>AF-2 Chủ tin theo dõi phiên căn mình → bid feed + kết quả (không được tạo registration — EF-3 UC-07).</li></ul><p><strong>EF</strong></p><ul><li>EF-1 Bid thấp hơn min → 422 <code>BID_TOO_LOW</code> (details.minAcceptable, FE highlight lại ô nhập).</li><li>EF-2 Bid đúng lúc kết thúc (race endAt): server nhận nếu <code>bidTime ≤ effective endAt</code> đã áp anti-snipe; nếu job kết thúc thắng → 409 <code>AUCTION_NOT_IN_PROGRESS</code> — <strong>quyết thắng/thua do lock transaction, không do đồng hồ client (NFR-P-04)</strong>.</li><li>EF-3 2 bid cùng giá trị cùng thời điểm: row-lock serialize — bid commit trước được nhận, bid sau thành <code>BID_TOO_LOW</code> (không &gt; current+step). Tie-break timestamp server.</li><li>EF-4 Mất mạng sau khi gửi: FE dùng idempotency-key per attempt; resume kiểm tra trạng thái, không báo lỗi ghost.</li><li>EF-5 User bị ADMIN suspend giữa phiên (hy hữu — BR-IDT-05 chặn suspend khi registration ACTIVE; rủi ro còn lại: user SUSPENDED từ trước nhưng registration vẫn ACTIVE — job phải đồng bộ): registration REJECTED, các bid <strong>đã submit vẫn giữ giá trị</strong> (không hồi tố — BR-AU-17); không bid tiếp.</li></ul><p><strong>Links</strong>: FR-AU-06..08, BR-AU-08..18, flow docs/04 F-01.</p><hr><h2 id="uc-09-—-thanh-toan-phien-trung-settlement" tabindex="-1">UC-09 — Thanh toán phiên trúng (settlement) <a class="header-anchor" href="#uc-09-—-thanh-toan-phien-trung-settlement" aria-label="Permalink to &quot;UC-09 — Thanh toán phiên trúng (settlement)&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên trúng đấu giá; ADMIN (xác nhận manual, confirm completed); chủ nhà (nhận NTF) <strong>Preconditions</strong>: phiên AWARDED; order PENDING. <strong>Postconditions</strong>: order COMPLETED → listing SOLD, NTF-04; hoặc EXPIRED → forfeit + listing LISTED + privilege SUSPENDED.</p><p><strong>MF</strong></p><ol><li>Người trúng nhận email + trong app banner &quot;Bạn đã trúng {unitCode}&quot;; xem breakdown: giá trúng, phí đấu giá %, trừ cọc, còn phải trả, hạn 24h (đồng hồ đếm).</li><li>&quot;Thanh toán ngay&quot; → intent gateway (FR-PAY-04) / manual transfer.</li><li>Webhook SUCCESS → order PAID (tiền về tài khoản sàn).</li><li>ADMIN đối chiếu, xác nhận chứng từ, bấm <code>CONFIRM COMPLETED</code> → listing SOLD; NTF-04 tới chủ nhà; hợp đồng công chứng thực hiện <strong>ngoài hệ thống</strong> (An Phuc CS điều phối — non-goal phần pháp lý giấy tờ).</li></ol><p><strong>AF-1</strong> Manual: ADMIN confirm payment trước, rồi confirm completed trong một thao tác. <strong>EF-1</strong> Quá payBy → job EXPIRED: registration→FORFEITED (cọc không hoàn, biên bản audit), order EXPIRED, listing→LISTED, user privilege SUSPENDED (chỉ ADMIN mở lại, lý do bắt buộc). <strong>Không tự trao giải cho người thứ hai trong v1</strong> (BR-AU-18, chờ pháp chế OQ-4). <strong>EF-2</strong> Gateway báo thành công trùng lặp → idempotent, order không double-apply. <strong>EF-3</strong> Người trúng khiếu nại (nhà lỗi thực tế so với tin): ngoài scope tiền; CS xử lý offline; ADMIN có thể <code>CANCEL_ORDER_WITH_REFUND</code> (manual, audit) → tiền hoàn gateway, listing về LISTED.</p><p><strong>Links</strong>: FR-AU-09, FR-PAY-04/05, BR-AU-15..18, flow docs/04 F-03.</p><hr><h2 id="uc-10-—-mua-goi-vip" tabindex="-1">UC-10 — Mua gói VIP <a class="header-anchor" href="#uc-10-—-mua-goi-vip" aria-label="Permalink to &quot;UC-10 — Mua gói VIP&quot;">​</a></h2><p><strong>Actor</strong>: Thành viên (chủ nhà) <strong>Preconditions</strong>: User KYC APPROVED (chỉ gói phục vụ đăng bán — BR-PKG-01). <strong>Postconditions</strong>: subscription ACTIVE; hạn mức FR-HS-10 tăng ngay; badge VIP trên tin.</p><p><strong>MF (khớp ví dụ nghiệp vụ: &quot;mua gói VIP → kiểm tra điều kiện → thanh toán → xác minh giao dịch → kích hoạt → thông báo&quot;)</strong></p><ol><li>Vào <code>/packages</code> → chọn VIP_STANDARD/VIP_PRO → trang xác nhận (giá, 30 ngày, quyền lợi, <strong>cảnh báo upgrade mất phần còn lại nếu đang có gói khác</strong>).</li><li>Kiểm điều kiện (KYC, không có order đấu giá đang chờ? — không ràng buộc) → &quot;Thanh toán&quot;.</li><li>Intent → gateway → webhook xác minh giao dịch (checksum + amount khớp).</li><li>Kích hoạt subscription ngay (BR-PKG-03 cộng dồn nếu cùng gói; nếu đổi gói: SUPERSEDED cũ + ACTIVE mới).</li><li>NTF + redirect dashboard &quot;VIP đã kích hoạt&quot;; hạn mức hiển thị mới (đã dùng X/50).</li></ol><p><strong>AF-1</strong> Gia hạn gói đang ACTIVE cùng package → endsAt += 30d. <strong>AF-2</strong> Thanh toán thất bại/hủy tại gateway → intent FAILED, subscription không đổi; user thử lại. <strong>EF-1</strong> Webhook đến trước khi FE redirect về: trạng thái đã ACTIVE — FE poll <code>/users/me/subscriptions</code> khi resume, hiển thị đúng. <strong>EF-2</strong> Gateway down: user chọn manual transfer (FR-PAY-03), ADMIN đối soát confirm — flow tiền chung docs/04 F-06. <strong>EF-3</strong> Duplicate webhook → idempotent theo gatewayTxnRef.</p><p><strong>Links</strong>: FR-PKG-01..04, BR-PKG-01..06, flow docs/04 F-06.</p><hr><h2 id="uc-11-—-admin-tao-van-hanh-phien-đau-gia" tabindex="-1">UC-11 — ADMIN tạo &amp; vận hành phiên đấu giá <a class="header-anchor" href="#uc-11-—-admin-tao-van-hanh-phien-đau-gia" aria-label="Permalink to &quot;UC-11 — ADMIN tạo &amp; vận hành phiên đấu giá&quot;">​</a></h2><p><strong>Actor</strong>: Quản trị viên <strong>Preconditions</strong>: Listing APPROVED/LISTED; không có phiên nào khác chưa kết thúc cho cùng listing. <strong>Postconditions</strong>: Phiên PUBLISHED public (notice ≥ 7 ngày), hoặc CANCELLED refund đủ.</p><p><strong>MF</strong></p><ol><li><code>/admin/auctions</code> → &quot;Tạo phiên&quot;: chọn listing (chỉ LISTED), cấu hình openingPrice (gợi ý = giá rao, editable), stepPrice, depositPercent, auctionFeePercent, startAt/endAt (end−start ≤ 24h), kiểm auto noticeAt ≥ start−7d.</li><li>DRAFT hoàn tất → &quot;Công bố&quot;: PUBLISHED; listing→RESERVED; trang public xuất hiện upcoming; lịch đăng ký mở.</li><li>Trong phiên: giám sát live (bid feed, participants, anti-snipe log).</li><li>Sau kết thúc: duyệt settlement (UC-09), hoặc thao tác CANCEL (trước khi IN_PROGRESS; lý do; refund tự động).</li></ol><p><strong>AF-1</strong> ADMIN sửa cấu hình khi PUBLISHED nhưng chưa có registration → cho phép (audit); <strong>đã có registration ACTIVE → khóa</strong> (409 <code>AUCTION_LOCKED</code>) vì cọc đã thu theo cấu hình cũ. <strong>EF-1</strong> Ngày công bố &lt; 7 ngày → 422 <code>NOTICE_TOO_SHORT</code> (BR-AU-03). <strong>EF-2</strong> Start đã qua mà chưa publish → DRAFT hết hạn, ADMIN chỉnh ngày.</p><p><strong>Links</strong>: FR-AU-01/02/10, BR-AU-01..04, docs/04 F-01 (swimlane ADMIN).</p><hr><h2 id="uc-12-—-admin-quan-ly-nguoi-dung-xu-ly-vi-pham" tabindex="-1">UC-12 — ADMIN quản lý người dùng &amp; xử lý vi phạm <a class="header-anchor" href="#uc-12-—-admin-quan-ly-nguoi-dung-xu-ly-vi-pham" aria-label="Permalink to &quot;UC-12 — ADMIN quản lý người dùng &amp; xử lý vi phạm&quot;">​</a></h2><p><strong>Actor</strong>: Quản trị viên <strong>MF</strong>: tìm user (email/phone/name) → xem hồ sơ: KYC, listings, registrations, orders, privilege → SUSPEND/ACTIVATE (reason) hoặc mở <code>auctionPrivilege</code> cho user vi phạm settlement. <strong>EF</strong>: user có registration ACTIVE trong phiên đang IN_PROGRESS → suspend account blocked 409 <code>USER_HAS_ACTIVE_AUCTION</code> (BR-IDT-05) — vi phạm đấu giá xử lý bằng privilege flag, không suspend toàn account giữa phiên. <strong>Links</strong>: FR-ADM-03, BR-IDT-04/05, BR-AU-17.</p>',98))])}const F=h(u,[["render",d]]);export{I as __pageData,F as default};
